type FilterPredicate = (item: string) => boolean;

function customFilter(wordsList: string[], predicate: FilterPredicate): string[] {
  const filteredResult: string[] = [];
  for (const word of wordsList) {
    if (predicate(word)) {
      filteredResult.push(word);
    }
  }
  return filteredResult;
}

const names = ["Ahmed", "Omar", "Ali", "Mahmoud"];
