// تصميم سيء جداً (Bad Design):
type BadApiResponse = {
  status: "loading" | "success" | "error";
  data?: User[];
  errorMessage?: string;
};

interface LoadingState {
  status: "loading"; // الـ Discriminant
}

interface SuccessState {
  status: "success"; // الـ Discriminant
  data: string[];
}

interface ErrorState {
  status: "error";   // الـ Discriminant
  errorMessage: string;
  errorCode: number;
}

// دمج كل الحالات في Union واحد:
type ApiResponseState = LoadingState | SuccessState | ErrorState;

function renderUi(state: ApiResponseState) {
  switch (state.status) {
    case "loading":
      console.log("Showing spinner...");
      break;

    case "success":
      // هنا TypeScript متأكدة إن data موجودة:
      console.log(`Loaded ${state.data.length} items`);
      break;

    case "error":
      // هنا TypeScript متأكدة إن errorMessage و errorCode موجودين:
      console.log(`Error ${state.errorCode}: ${state.errorMessage}`);
      break;
  }
}

function assertNever(value: never): never {
  throw new Error(`Unhandled discriminated union member: ${JSON.stringify(value)}`);
}

function handleStateWithSafety(state: ApiResponseState): string {
  switch (state.status) {
    case "loading":
      return "Loading spinner";
    case "success":
      return `Data count: ${state.data.length}`;
    case "error":
      return `Failed: ${state.errorMessage}`;
    default:
      // لو كل الحالات متغطية، نوع state هنا هيكون never:
      return assertNever(state);
  }
}

