    // جوه البلوك ده: value نوعه number مؤكد
    console.log(value.toFixed(2));
    return;
  }
  // بعد الـ return: مستحيل يكون number! نوعه هنا string مؤكد:
  console.log(value.toUpperCase());
}

function formatInput(input: string | number | boolean): string {
  if (typeof input === "string") {
    return input.trim();
  } else if (typeof input === "number") {
    return input.toFixed(2);
  } else {
    return input ? "YES" : "NO"; // input هنا boolean مؤكد
  }
}

function inspectData(data: object | null) {
  if (typeof data === "object" && data !== null) {
    // هنا بس نضمن إنه Object حقيقي ومش null
    console.log(Object.keys(data));
  }
}

function logTimestamp(dateOrString: Date | string): string {
  if (dateOrString instanceof Date) {
    // نوع المتغير هنا Date مؤكد:
    return dateOrString.toISOString();
  }
  // نوع المتغير هنا string مؤكد:
  return dateOrString;
}

interface AdminUser {
  id: string;
  role: "admin";
  permissions: string[];
}

interface GuestUser {
  id: string;
  role: "guest";
  anonymousSessionId: string;
}

function processUser(user: AdminUser | GuestUser) {
  if ("permissions" in user) {
    // TypeScript متأكدة إن user هنا هو AdminUser:
    console.log(`Admin with ${user.permissions.length} permissions`);
  } else {
    // TypeScript متأكدة إن user هنا هو GuestUser:
    console.log(`Guest session: ${user.anonymousSessionId}`);
  }
}

function checkStatus(apiStatus: "success" | "error", flag: boolean | "success") {
  if (apiStatus === flag) {
    // الاحتمال الوحيد المتطابق بينهم هو "success":
    // نوع apiStatus و flag هنا هو "success" مؤكد!
    console.log("Both matched on success");
  }
}

function greet(name: string | null | undefined) {
  if (name) {
    // هنا name ليس null ولا undefined ولا string فاضي ""
    console.log(`Hello, ${name.toUpperCase()}!`);
  }
}

interface ApiResponseSuccess {
  data: { userId: number; token: string };
}

// دالة حارس النوع المخصصة:
function isApiResponseSuccess(response: unknown): response is ApiResponseSuccess {
  return (
    typeof response === "object" &&
    response !== null &&
    "data" in response &&
    typeof (response as any).data?.token === "string"
  );
}

function handlePayload(payload: unknown) {
  if (isApiResponseSuccess(payload)) {
    // هنا TypeScript عارفة إن payload نوعه ApiResponseSuccess تماماً:
    console.log("User Token:", payload.data.token);
  } else {
    console.error("Invalid response shape");
  }
}

function renderContent(content: React.ReactNode) {
  if (typeof content === "string") {
    return <p>{content}</p>;
  }
  return content;
}

try {
  await database.connect();
} catch (error: unknown) {
  if (error instanceof Error) {
    // تضييق النوع للوصول لـ message بأمان:
    logger.error(`Connection failed: ${error.message}`);
  } else {
    logger.error(`An unexpected non-standard error occurred: ${String(error)}`);
  }
}

