import { z } from "zod";

// تعريف Schema لشكل المستخدم:
export const UserSchema = z.object({
  id: z.string().uuid("Invalid UUID format"),
  name: z.string().min(2, "Name must be at least 2 characters"),
  email: z.string().email("Invalid email address"),
  age: z.number().int().positive().optional(),
  role: z.enum(["admin", "editor", "viewer"]).default("viewer"),
  isActive: z.boolean().default(true)
});

// استخراج الـ TypeScript Type تلقائياً:
export type User = z.infer<typeof UserSchema>;

/*
الناتج اللي الكومبايلر بيشوفه تلقائياً:
type User = {
  id: string;
  name: string;
  email: string;
  age?: number | undefined;
  role: "admin" | "editor" | "viewer";
  isActive: boolean;
}
*/

async function fetchAndValidateUser(userId: string): Promise<User | null> {
  const rawResponse = await fetch(`/api/users/${userId}`).then(res => res.json());

  // فحص الداتا بالـ Schema:
  const validationResult = UserSchema.safeParse(rawResponse);

  if (!validationResult.success) {
    console.error("API Contract Violation! Errors:", validationResult.error.format());
    return null;
  }

  // هنا TypeScript متأكدة بنسبة 100% إن validationResult.data هو User سليم وآمن:
  return validationResult.data;
}

