import React, { type ReactNode } from "react";

export interface ButtonProps {
  variant?: "primary" | "secondary" | "danger";
  size?: "sm" | "md" | "lg";
  isLoading?: boolean;
  onClick: (event: React.MouseEvent<HTMLButtonElement>) => void;
  children: ReactNode; // يقبل أي عنصر JSX صالح (نص، أرقام، مكونات أخرى)
}

export function Button({
  variant = "primary",
  size = "md",
  isLoading = false,
  onClick,
  children
}: ButtonProps) {
  return (
    <button
      className={`btn btn-${variant} btn-${size}`}
      onClick={onClick}
      disabled={isLoading}
    >
      {isLoading ? "جاري التحميل..." : children}
    </button>
  );
}

export function SearchForm() {
  // 1. حدث تغيير محتوى حقل الإدخال:
  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    console.log("Current value:", event.target.value);
  };

  // 2. حدث إرسال النموذج (Submit):
  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    console.log("Form submitted safely");
  };

  // 3. حدث الضغط على أزرار الكيبورد:
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      console.log("Enter key pressed!");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" onChange={handleInputChange} onKeyDown={handleKeyDown} />
      <button type="submit">بحث</button>
    </form>
  );
}

interface User {
  id: string;
  name: string;
}

// 1. نوع بدائي مع قيمة أولية (TypeScript بتستنتجه تلقائياً):
const [count, setCount] = React.useState(0); // number

// 2. كائن يبدأ بـ null (لازم Generic Annotation):
const [currentUser, setCurrentUser] = React.useState<User | null>(null);

// 3. مصفوفة تبدأ فارغة:
const [itemsList, setItemsList] = React.useState<string[]>([]);

// 1. DOM Element Reference (يبدأ دائماً بـ null):
const searchInputRef = React.useRef<HTMLInputElement>(null);

function focusInput() {
  searchInputRef.current?.focus(); // آمن باستخدام Optional Chaining
}

// 2. Mutable Value (تخزين مؤقت لا يسبب إعادة رسم):
const timerIdRef = React.useRef<number | undefined>(undefined);

interface CounterState {
  count: number;
}

type CounterAction =
  | { type: "INCREMENT"; step?: number }
  | { type: "DECREMENT"; step?: number }
  | { type: "RESET" };

function counterReducer(state: CounterState, action: CounterAction): CounterState {
  switch (action.type) {
    case "INCREMENT":
      return { count: state.count + (action.step ?? 1) };
    case "DECREMENT":
      return { count: state.count - (action.step ?? 1) };
    case "RESET":
      return { count: 0 };
  }
}

export function Counter() {
  const [state, dispatch] = React.useReducer(counterReducer, { count: 0 });
  return (
    <div>
      <p>Count: {state.count}</p>
      <button onClick={() => dispatch({ type: "INCREMENT", step: 5 })}>+5</button>
      <button onClick={() => dispatch({ type: "RESET" })}>Reset</button>
    </div>
  );
}

interface SelectProps<TOption> {
  options: TOption[];
  getOptionLabel: (option: TOption) => string;
  getOptionValue: (option: TOption) => string;
  onSelect: (selected: TOption) => void;
}

export function Select<TOption>({
  options,
  getOptionLabel,
  getOptionValue,
  onSelect
}: SelectProps<TOption>) {
  return (
    <select
      onChange={(e) => {
        const found = options.find((opt) => getOptionValue(opt) === e.target.value);
        if (found) onSelect(found);
      }}
    >
      {options.map((opt) => (
        <option key={getOptionValue(opt)} value={getOptionValue(opt)}>
          {getOptionLabel(opt)}
        </option>
      ))}
    </select>
  );
}

