import { Request, Response, NextFunction } from "express";

// 1. تعريف عقود البيانات للـ Endpoint:
interface GetUserParams {
  userId: string;
}

interface UpdateUserBody {
  name: string;
  email: string;
}

interface UserQueryFilters {
  includeOrders?: "true" | "false";
}

interface UserResponseData {
  id: string;
  name: string;
  email: string;
}

// 2. دالة الـ Controller مع الأنواع الدقيقة:
export async function updateUserController(
  req: Request<GetUserParams, UserResponseData, UpdateUserBody, UserQueryFilters>,
  res: Response<UserResponseData>,
  next: NextFunction
) {
  try {
    const { userId } = req.params;     // نوعها string
    const { name, email } = req.body;  // أنواعهم string
    const { includeOrders } = req.query; // نوعها "true" | "false" | undefined

    console.log(`Updating user ${userId} with name: ${name}`);

    return res.status(200).json({
      id: userId,
      name,
      email
    });
  } catch (error) {
    next(error);
  }
}

import type { UserResponseDTO } from "../models/user.dto";

declare global {
  namespace Express {
    interface Request {
      user?: UserResponseDTO; // إضافة خاصية user لكائن Request
    }
  }
}

export {};

export function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.user) {
    return res.status(401).json({ message: "Unauthorized" });
  }
  console.log("Logged in as:", req.user.email);
  next();
}

export interface IUserRepository {
  findById(id: string): Promise<UserDatabaseEntity | null>;
  findByEmail(email: string): Promise<UserDatabaseEntity | null>;
  create(data: CreateUserDTO): Promise<UserDatabaseEntity>;
}

export class UserService {
  constructor(private readonly userRepo: IUserRepository) {}

  async getUserProfile(id: string): Promise<UserResponseDTO> {
    const user = await this.userRepo.findById(id);
    if (!user) {
      throw new NotFoundError("User", id);
    }
    return {
      id: user.id,
      email: user.email,
      createdAt: user.created_at.toISOString()
    };
  }
}

