import { z } from "zod";

// 1. Zod Schema للتحقق في الـ Frontend والـ Backend معاً:
export const CreateUserSchema = z.object({
  name: z.string().min(2, "الاسم يجب أن يكون حرفين على الأقل"),
  email: z.string().email("البريد الإلكتروني غير صالح"),
  role: z.enum(["admin", "member"]).default("member")
});

// 2. استخراج أنواع البيانات الثابتة:
export type CreateUserRequestDTO = z.infer<typeof CreateUserSchema>;

export interface UserResponseDTO {
  id: string;
  name: string;
  email: string;
  role: "admin" | "member";
  createdAt: string;
}

import { Request, Response, NextFunction } from "express";
import { CreateUserSchema, type CreateUserRequestDTO, type UserResponseDTO } from "@my-app/shared";

export async function createUserHandler(
  req: Request<{}, UserResponseDTO, CreateUserRequestDTO>,
  res: Response<UserResponseDTO>,
  next: NextFunction
) {
  try {
    // 1. التحقق من صحة البيانات القادمة في الـ Runtime:
    const validatedData = CreateUserSchema.parse(req.body);

    // 2. الحفظ في قاعدة البيانات:
    const newUser: UserResponseDTO = {
      id: `usr_${Date.now()}`,
      name: validatedData.name,
      email: validatedData.email,
      role: validatedData.role,
      createdAt: new Date().toISOString()
    };

    return res.status(201).json(newUser);
  } catch (error) {
    next(error);
  }
}

import React, { useState } from "react";
import { CreateUserSchema, type CreateUserRequestDTO, type UserResponseDTO } from "@my-app/shared";

export function UserRegistrationForm() {
  const [formData, setFormData] = useState<CreateUserRequestDTO>({
    name: "",
    email: "",
    role: "member"
  });

  const [formErrors, setFormErrors] = useState<Record<string, string>>({});
  const [createdUser, setCreatedUser] = useState<UserResponseDTO | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // 1. فحص محلي فوري قبل الإرسال باستخدام نفس الـ Schema:
    const validation = CreateUserSchema.safeParse(formData);
    if (!validation.success) {
      const fieldErrors: Record<string, string> = {};
      for (const issue of validation.error.issues) {
        fieldErrors[String(issue.path[0])] = issue.message;
      }
      setFormErrors(fieldErrors);
      return;
    }

    setFormErrors({});

    // 2. الإرسال للسيرفر:
    const response = await fetch("/api/users", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(validation.data)
    });

    if (response.ok) {
      const data: UserResponseDTO = await response.json();
      setCreatedUser(data);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 400, margin: "20px auto" }}>
      <h2>تسجيل مستخدم جديد</h2>
      <div>
        <label>الاسم:</label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
        />
        {formErrors.name && <p style={{ color: "red" }}>{formErrors.name}</p>}
      </div>

      <div>
        <label>البريد الإلكتروني:</label>
        <input
          type="email"
          value={formData.email}
          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
        />
        {formErrors.email && <p style={{ color: "red" }}>{formErrors.email}</p>}
      </div>

      <button type="submit" style={{ marginTop: 10 }}>تسجيل</button>

      {createdUser && (
        <div style={{ marginTop: 20, padding: 10, background: "#e6ffe6" }}>
          <p>تم التسجيل بنجاح! كود المستخدم: {createdUser.id}</p>
        </div>
      )}
    </form>
  );
}
